    struct entry { char const* name; char const* doc; };
    inline entry const sDocs[] =
    {
        { "", "Subprocesses with accessible I/O streams\n\nThis module allows you to spawn processes, connect to their\ninput/output/error pipes, and obtain their return codes.\n\nFor a complete description of this module see the Python documentation.\n\nMain API\n========\nrun(...): Runs a command, waits for it to complete, then returns a\n          CompletedProcess instance.\nPopen(...): A class for flexibly executing a command in a new process\n\nConstants\n---------\nDEVNULL: Special value that indicates that os.devnull should be used\nPIPE:    Special value that indicates a pipe should be created\nSTDOUT:  Special value that indicates that stderr should go to stdout\n\n\nOlder API\n=========\ncall(...): Runs a command, waits for it to complete, then returns\n    the return code.\ncheck_call(...): Same as call() but raises CalledProcessError()\n    if return code is not 0\ncheck_output(...): Same as check_call() but returns the contents of\n    stdout instead of a return code\ngetoutput(...): Runs a command in the shell, waits for it to complete,\n    then returns the output\ngetstatusoutput(...): Runs a command in the shell, waits for it to complete,\n    then returns a (exitcode, output) tuple\n" },
        { "CalledProcessError", "Raised when run() is called with check=True and the process\nreturns a non-zero exit status.\n\nAttributes:\n  cmd, returncode, stdout, stderr, output\n" },
        { "CompletedProcess", "A process that has finished running.\n\nThis is returned by run().\n\nAttributes:\n  args: The list or str args passed to run().\n  returncode: The exit code of the process, negative for signals.\n  stdout: The standard output (None if not captured).\n  stderr: The standard error (None if not captured).\n" },
        { "CompletedProcess.check_returncode", "Raise CalledProcessError if the exit code is non-zero." },
        { "Popen", "Execute a child program in a new process.\n\nFor a complete description of the arguments see the Python documentation.\n\nArguments:\n  args: A string, or a sequence of program arguments.\n\n  bufsize: supplied as the buffering argument to the open() function when\n      creating the stdin/stdout/stderr pipe file objects\n\n  executable: A replacement program to execute.\n\n  stdin, stdout and stderr: These specify the executed programs' standard\n      input, standard output and standard error file handles, respectively.\n\n  preexec_fn: (POSIX only) An object to be called in the child process\n      just before the child is executed.\n\n  close_fds: Controls closing or inheriting of file descriptors.\n\n  shell: If true, the command will be executed through the shell.\n\n  cwd: Sets the current directory before the child is executed.\n\n  env: Defines the environment variables for the new process.\n\n  text: If true, decode stdin, stdout and stderr using the given encoding\n      (if set) or the system default otherwise.\n\n  universal_newlines: Alias of text, provided for backwards compatibility.\n\n  startupinfo and creationflags (Windows only)\n\n  restore_signals (POSIX only)\n\n  start_new_session (POSIX only)\n\n  process_group (POSIX only)\n\n  group (POSIX only)\n\n  extra_groups (POSIX only)\n\n  user (POSIX only)\n\n  umask (POSIX only)\n\n  pass_fds (POSIX only)\n\n  encoding and errors: Text mode encoding and error handling to use for\n      file objects stdin, stdout and stderr.\n\nAttributes:\n    stdin, stdout, stderr, pid, returncode\n" },
        { "Popen.__init__", "Create new Popen instance." },
        { "Popen.communicate", "Interact with process: Send data to stdin and close it.\nRead data from stdout and stderr, until end-of-file is\nreached.  Wait for process to terminate.\n\nThe optional \"input\" argument should be data to be sent to the\nchild process, or None, if no data should be sent to the child.\ncommunicate() returns a tuple (stdout, stderr).\n\nBy default, all communication is in bytes, and therefore any\n\"input\" should be bytes, and the (stdout, stderr) will be bytes.\nIf in text mode (indicated by self.text_mode), any \"input\" should\nbe a string, and (stdout, stderr) will be strings decoded\naccording to locale encoding, or by \"encoding\" if set. Text mode\nis triggered by setting any of text, encoding, errors or\nuniversal_newlines.\n" },
        { "Popen.poll", "Check if child process has terminated. Set and return returncode\nattribute." },
        { "Popen._remaining_time", "Convenience for _communicate when computing timeouts." },
        { "Popen._check_timeout", "Convenience for checking if a timeout has expired." },
        { "Popen.wait", "Wait for child process to terminate; returns self.returncode." },
        { "Popen._on_error_fd_closer", "Helper to ensure file descriptors opened in _get_handles are closed" },
        { "Popen._get_handles", "Construct and return tuple with IO objects:\np2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite\n" },
        { "Popen._posix_spawn", "Execute program using os.posix_spawn()." },
        { "Popen._execute_child", "Execute program (POSIX version)" },
        { "Popen._handle_exitstatus", "All callers to this function MUST hold self._waitpid_lock." },
        { "Popen._internal_poll", "Check if child process has terminated.  Returns returncode\nattribute.\n\nThis method is called by __del__, so it cannot reference anything\noutside of the local scope (nor can any methods it calls).\n\n" },
        { "Popen._try_wait", "All callers to this function MUST hold self._waitpid_lock." },
        { "Popen._wait", "Internal implementation of wait() on POSIX." },
        { "Popen.send_signal", "Send a signal to the process." },
        { "Popen.terminate", "Terminate the process with SIGTERM\n            " },
        { "Popen.kill", "Kill the process with SIGKILL\n            " },
        { "TimeoutExpired", "This exception is raised when the timeout expires while waiting for a\nchild process.\n\nAttributes:\n    cmd, output, stdout, stderr, timeout\n" },
        { "_args_from_interpreter_flags", "Return a list of command-line arguments reproducing the current\nsettings in sys.flags, sys.warnoptions and sys._xoptions." },
        { "_optim_args_from_interpreter_flags", "Return a list of command-line arguments reproducing the current\noptimization settings in sys.flags." },
        { "_use_posix_spawn", "Check if posix_spawn() can be used for subprocess.\n\nsubprocess requires a posix_spawn() implementation that properly reports\nerrors to the parent process, & sets errno on the following failures:\n\n* Process attribute actions failed.\n* File actions failed.\n* exec() failed.\n\nPrefer an implementation which can use vfork() in some cases for best\nperformance.\n" },
        { "call", "Run command with arguments.  Wait for command to complete or\nfor timeout seconds, then return the returncode attribute.\n\nThe arguments are the same as for the Popen constructor.  Example:\n\nretcode = call([\"ls\", \"-l\"])\n" },
        { "check_call", "Run command with arguments.  Wait for command to complete.  If\nthe exit code was zero then return, otherwise raise\nCalledProcessError.  The CalledProcessError object will have the\nreturn code in the returncode attribute.\n\nThe arguments are the same as for the call function.  Example:\n\ncheck_call([\"ls\", \"-l\"])\n" },
        { "check_output", "Run command with arguments and return its output.\n\nIf the exit code was non-zero it raises a CalledProcessError.  The\nCalledProcessError object will have the return code in the returncode\nattribute and output in the output attribute.\n\nThe arguments are the same as for the Popen constructor.  Example:\n\n>>> check_output([\"ls\", \"-l\", \"/dev/null\"])\nb'crw-rw-rw- 1 root root 1, 3 Oct 18  2007 /dev/null\\n'\n\nThe stdout argument is not allowed as it is used internally.\nTo capture standard error in the result, use stderr=STDOUT.\n\n>>> check_output([\"/bin/sh\", \"-c\",\n...               \"ls -l non_existent_file ; exit 0\"],\n...              stderr=STDOUT)\nb'ls: non_existent_file: No such file or directory\\n'\n\nThere is an additional optional argument, \"input\", allowing you to\npass a string to the subprocess's stdin.  If you use this argument\nyou may not also use the Popen constructor's \"stdin\" argument, as\nit too will be used internally.  Example:\n\n>>> check_output([\"sed\", \"-e\", \"s/foo/bar/\"],\n...              input=b\"when in the course of fooman events\\n\")\nb'when in the course of barman events\\n'\n\nBy default, all communication is in bytes, and therefore any \"input\"\nshould be bytes, and the return value will be bytes.  If in text mode,\nany \"input\" should be a string, and the return value will be a string\ndecoded according to locale encoding, or by \"encoding\" if set. Text mode\nis triggered by setting any of text, encoding, errors or universal_newlines.\n" },
        { "getoutput", "Return output (stdout or stderr) of executing cmd in a shell.\n\nLike getstatusoutput(), except the exit status is ignored and the return\nvalue is a string containing the command's output.  Example:\n\n>>> import subprocess\n>>> subprocess.getoutput('ls /bin/ls')\n'/bin/ls'\n" },
        { "getstatusoutput", "Return (exitcode, output) of executing cmd in a shell.\n\nExecute the string 'cmd' in a shell with 'check_output' and\nreturn a 2-tuple (status, output). The locale encoding is used\nto decode the output and process newlines.\n\nA trailing newline is stripped from the output.\nThe exit status for the command can be interpreted\naccording to the rules for the function 'wait'. Example:\n\n>>> import subprocess\n>>> subprocess.getstatusoutput('ls /bin/ls')\n(0, '/bin/ls')\n>>> subprocess.getstatusoutput('cat /bin/junk')\n(1, 'cat: /bin/junk: No such file or directory')\n>>> subprocess.getstatusoutput('/bin/junk')\n(127, 'sh: /bin/junk: not found')\n>>> subprocess.getstatusoutput('/bin/kill $$')\n(-15, '')\n" },
        { "list2cmdline", "\nTranslate a sequence of arguments into a command line\nstring, using the same rules as the MS C runtime:\n\n1) Arguments are delimited by white space, which is either a\n   space or a tab.\n\n2) A string surrounded by double quotation marks is\n   interpreted as a single argument, regardless of white space\n   contained within.  A quoted string can be embedded in an\n   argument.\n\n3) A double quotation mark preceded by a backslash is\n   interpreted as a literal double quotation mark.\n\n4) Backslashes are interpreted literally, unless they\n   immediately precede a double quotation mark.\n\n5) If backslashes immediately precede a double quotation mark,\n   every pair of backslashes is interpreted as a literal\n   backslash.  If the number of backslashes is odd, the last\n   backslash escapes the next double quotation mark as\n   described in rule 3.\n" },
        { "run", "Run command with arguments and return a CompletedProcess instance.\n\nThe returned instance will have attributes args, returncode, stdout and\nstderr. By default, stdout and stderr are not captured, and those attributes\nwill be None. Pass stdout=PIPE and/or stderr=PIPE in order to capture them,\nor pass capture_output=True to capture both.\n\nIf check is True and the exit code was non-zero, it raises a\nCalledProcessError. The CalledProcessError object will have the return code\nin the returncode attribute, and output & stderr attributes if those streams\nwere captured.\n\nIf timeout (seconds) is given and the process takes too long,\n a TimeoutExpired exception will be raised.\n\nThere is an optional argument \"input\", allowing you to\npass bytes or a string to the subprocess's stdin.  If you use this argument\nyou may not also use the Popen constructor's \"stdin\" argument, as\nit will be used internally.\n\nBy default, all communication is in bytes, and therefore any \"input\" should\nbe bytes, and the stdout and stderr will be bytes. If in text mode, any\n\"input\" should be a string, and stdout and stderr will be strings decoded\naccording to locale encoding, or by \"encoding\" if set. Text mode is\ntriggered by setting any of text, encoding, errors or universal_newlines.\n\nThe other arguments are the same as for the Popen constructor.\n" },
    };
